import mongoose from 'mongoose'

/**
 * Materialized time-slots generated from the restaurant's schedule.
 * The agent never reasons about open/close hours directly — it always
 * reads from this collection via the availability tool.
 *
 * Slots are generated by a nightly job (see jobs/generateSlots.js) and
 * upserted so re-runs never reset capacityRemaining.
 */
const restaurantSlotSchema = new mongoose.Schema(
  {
    restaurantId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Restaurant',
      required: true,
    },
    startUtc: {
      type: Date,
      required: true,
    },
    localDate: {
      type: String, // "2026-11-03"
      required: true,
    },
    capacityTotal: {
      type: Number,
      required: true,
    },
    capacityRemaining: {
      type: Number,
      required: true,
    },
    status: {
      type: String,
      enum: ['open', 'closed'],
      default: 'open',
    },
  },
  { timestamps: true },
)

// Unique per restaurant + time. Prevents duplicate slots.
restaurantSlotSchema.index(
  { restaurantId: 1, startUtc: 1 },
  { unique: true },
)

// ESR: restaurantId + localDate (equality), startUtc (sort),
// capacityRemaining (range).  With projection {startUtc:1,
// capacityRemaining:1, _id:0} the availability query is covered.
restaurantSlotSchema.index({
  restaurantId: 1,
  localDate: 1,
  startUtc: 1,
  capacityRemaining: 1,
})

export default mongoose.models.RestaurantSlot ||
  mongoose.model('RestaurantSlot', restaurantSlotSchema, 'restaurant_slots')
